<!doctype html><html lang="id"><head><meta charset="utf-8"><title><?php echo html_escape($meeting->meeting_code); ?></title><style>body{font-family:Arial,sans-serif;color:#111;margin:32px}h1{font-size:24px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #999;padding:8px;vertical-align:top}@media print{body{margin:12mm}}</style></head><body><h1><?php echo html_escape($meeting->meeting_code . ' — ' . $meeting->meeting_title); ?></h1><p><?php echo html_escape($meeting->meeting_date . ' — ' . $meeting->location); ?></p><h2>Laporan M10</h2><ul><?php foreach ($reports as $report): ?><li><?php echo html_escape($report->report_number . ' — ' . $report->cycle_title_snapshot); ?></li><?php endforeach; ?></ul><h2>Peserta snapshot</h2><ul><?php foreach ($participants as $participant): ?><li><?php echo html_escape($participant->name_snapshot . ' — ' . $participant->role_snapshot . ' — ' . $participant->email_snapshot); ?></li><?php endforeach; ?></ul><h2>Keputusan dan tindakan</h2><table><thead><tr><th>No</th><th>Keputusan</th><th>Tindakan</th></tr></thead><tbody><?php foreach ($decisions as $decision): ?><tr><td><?php echo html_escape($decision->display_order); ?></td><td><?php echo nl2br(html_escape($decision->decision_text)); ?></td><td><?php echo nl2br(html_escape($decision->action_text)); ?></td></tr><?php endforeach; ?></tbody></table></body></html>
